/**
 * Purpose: estimates how a paragraph of Lexend Light breaks into lines in the PDF, from the font's real advance widths
 * (lib/textMetrics.data.ts, generated by scripts/gen-text-metrics.py) and greedy word wrapping like LibreOffice's (no
 * hyphenation, but a line may end after a hyphen, as LibreOffice's does; kerning is ignored, which the checks in
 * test-render.mjs --pdf tolerate). Used to keep a project description
 * together across page breaks (lib/docxData.ts): LibreOffice ignores widow / orphan control inside table cells, so the
 * template needs to know where the lines end. Pure; unit-tested in lib/textMetrics.test.ts.
 */
import { LEXEND_LIGHT_WIDTHS } from "./textMetrics.data";

const WIDTHS = new Map(LEXEND_LIGHT_WIDTHS.split(",").map((pair) => pair.split(":").map((h) => parseInt(h, 16)) as [number, number]));
const FALLBACK = WIDTHS.get(0x6f) ?? 600; // an unknown character counts as an "o"

/** The width of `text` in Lexend Light at `sizePt`, in points. */
export function textWidthPt(text: string, sizePt: number): number {
  let units = 0;
  for (const ch of text) units += WIDTHS.get(ch.codePointAt(0) ?? 0) ?? FALLBACK;
  return (units * sizePt) / 1000;
}

/** One line of the estimate: [start, end) offsets in the text, end excluding the space or line break that ends it. */
export type LineSpan = { start: number; end: number };

/** Where the lines of `text` would end in a column `widthPt` wide (hard line breaks start a new line). */
export function wrapLines(text: string, widthPt: number, sizePt: number): LineSpan[] {
  const lines: LineSpan[] = [];
  let offset = 0;
  for (const part of text.split("\n")) {
    // the pieces a line can end after: a word, or the part of a word up to a hyphen ("next-" / "day")
    const words = [...part.matchAll(/[^\s-]*-+|[^\s-]+/g)].map((m) => ({ start: offset + (m.index ?? 0), end: offset + (m.index ?? 0) + m[0].length }));
    let line: LineSpan | null = null;
    for (const w of words) {
      if (line && textWidthPt(text.slice(line.start, w.end), sizePt) <= widthPt) line.end = w.end;
      else {
        if (line) lines.push(line);
        line = { ...w }; // a word wider than the column stays on a line of its own
      }
    }
    lines.push(line ?? { start: offset, end: offset }); // an empty part is an empty line
    offset += part.length + 1;
  }
  return lines;
}

/**
 * A description cut for the page-break rule: up to `maxWhole` lines it stays whole (one unit); longer, it is cut into its
 * first 2 lines, the middle and its last 2 lines, so a page break inside it leaves at least 2 lines on each side.
 */
export function splitDescription(text: string, widthPt: number, sizePt: number, maxWhole = 6): { whole: true } | { whole: false; head: string; body: string; tail: string } {
  const lines = wrapLines(text, widthPt, sizePt);
  if (lines.length <= maxWhole) return { whole: true };
  const headEnd = lines[1].end;
  const tailStart = lines[lines.length - 2].start;
  return { whole: false, head: text.slice(0, headEnd).trim(), body: text.slice(headEnd, tailStart).trim(), tail: text.slice(tailStart).trim() };
}
